import{readFile,writeFile}from'node:fs/promises'
const args=process.argv.slice(2),model=args[args.indexOf('--model')+1]||'auto',pending=new Map();let text='',sessionId='fake-session',id=1000
const emit=packet=>process.stdout.write(JSON.stringify(packet)+'\n')
const reply=(request,result)=>emit({jsonrpc:'2.0',id:request.id,result})
const request=(method,params)=>new Promise(resolve=>{const number=id++;pending.set(number,resolve);emit({jsonrpc:'2.0',id:number,method,params})})
process.stdin.setEncoding('utf8');process.stdin.on('data',chunk=>{text+=chunk;let p;while((p=text.indexOf('\n'))>=0){const line=text.slice(0,p);text=text.slice(p+1);try{const r=JSON.parse(line);if(pending.has(r.id)){pending.get(r.id)(r);pending.delete(r.id)}else void handle(r)}catch{}}})
async function handle(r){if(r.method==='initialize')return reply(r,{protocolVersion:1,agentCapabilities:{loadSession:true}});if(r.method==='session/new'){await writeFile('.fake-session.json',JSON.stringify({model}));return reply(r,{sessionId,models:{currentModelId:model,availableModels:[{modelId:model,name:model},{modelId:'auto',name:'Auto'}]}})}if(r.method==='session/load'){await readFile('.fake-session.json');return reply(r,{models:{currentModelId:model,availableModels:[{modelId:model,name:model}]}})}if(r.method==='session/prompt'){const content=r.params.prompt[0].text;if(content.includes('WAIT_FOREVER'))return;const file=await request('fs/read_text_file',{path:'README.md'});if(file.error)return emit({jsonrpc:'2.0',id:r.id,error:{code:-1,message:file.error.message}});const output={status:'completed',summary:'已读取：'+file.result.content,evidence:['delegated fs'],artifacts:['README.md']};emit({jsonrpc:'2.0',method:'session/update',params:{sessionId,update:{sessionUpdate:'agent_message_chunk',content:{type:'text',text:JSON.stringify(output)}}}});emit({jsonrpc:'2.0',method:'session/update',params:{sessionId,update:{sessionUpdate:'usage_update',_meta:{usage:{prompt_tokens:12,completion_tokens:5,credit:0.1}}}}});return reply(r,{stopReason:'end_turn'})}}
